effect.shader:
// O filtro de textura da GPU (o do AE no render, medido): os pesos do bilinear andam em 1/256 de pixel.
vec2 pesoDaGpu(vec2 f) { return floor(f * 256.0 + 0.5) / 256.0; }

// O texel em níveis de 8 bits, inteiros.
vec4 nivel(vec4 c) { return floor(c * 255.0 + 0.5); }

void main() {
    ivec2 tam = textureSize(inputImg, 0);
    ivec2 aqui = min(ivec2(floor(acScreenNorm * vec2(tam))), tam - ivec2(1));
    vec4 original = texelFetch(inputImg, aqui, 0);

    // A camada do AE dentro do buffer: L px inteiros, centrada (a foto encaixada; o resto, a composição).
    ivec2 L = clamp(ivec2(floor(acCamada * vec2(tam) + 0.5)), ivec2(1), tam);
    ivec2 inicio = (tam - L) / 2;
    ivec2 q = aqui - inicio;
    if (any(lessThan(q, ivec2(0))) || any(greaterThanEqual(q, L))) {
        fragColor = original;        // fora da camada: no AE não há camada aqui
        return;
    }
    vec2 Lf = vec2(L);

    // O centro da imagem vai para `shiftCenterTo`: o pixel q lê a camada em q − deslocamento, com a volta.
    vec2 deslocamento = (shiftCenterTo - 0.5) * vec2(tam);
    vec2 X = vec2(q) - mod(deslocamento, Lf);
    vec2 base = floor(X);
    vec2 g = pesoDaGpu(X - base);
    ivec2 i0 = min(ivec2(mod(base, Lf)), L - ivec2(1));
    ivec2 i1 = min(ivec2(mod(base + 1.0, Lf)), L - ivec2(1));

    // Bilinear da cor RETA, como o AE (a cor dos pixels transparentes entra também). Em NÍVEIS (0..255)
    // inteiros: com os pesos em 1/256, a conta sai exata em float — e o empate de meio nível (o deslocamento
    // de meio pixel) arredonda para cima, como no AE, em vez de cair para qualquer lado.
    vec4 a = nivel(texelFetch(inputImg, inicio + ivec2(i0.x, i0.y), 0));
    vec4 b = nivel(texelFetch(inputImg, inicio + ivec2(i1.x, i0.y), 0));
    vec4 c = nivel(texelFetch(inputImg, inicio + ivec2(i0.x, i1.y), 0));
    vec4 d = nivel(texelFetch(inputImg, inicio + ivec2(i1.x, i1.y), 0));
    vec4 m = mix(mix(a, b, g.x), mix(c, d, g.x), g.y);

    // Blend With Original em cor pré-multiplicada, antes de arredondar.
    float r = blendWithOriginal;
    if (r > 0.0) {
        vec4 o = nivel(original);
        float alfa = mix(m.a, o.a, r);
        vec3 cor = mix(m.rgb * m.a, o.rgb * o.a, r);
        m = vec4(alfa > 0.0 ? cor / alfa : vec3(0.0), alfa);
    }

    // Uma vez só, no fim, em 8 bits (o AE em 8 bpc).
    fragColor = floor(clamp(m, 0.0, 255.0) + 0.5) / 255.0;
}
